<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Project = { id: string; name: string; description?: string; status?: string; version?: number };
type Task = { id: string; title: string; status?: string; projectId?: string; important?: boolean; urgent?: boolean; deadline?: string; estimatedDurationMinutes?: number; version?: number };
const projects = ref<Project[]>([]); const tasks = ref<Task[]>([]); const selected = ref<Project | null>(null); const loading = ref(false); const saving = ref(false); const error = ref(""); const dialog = ref(false); const taskDialog = ref(false); const taskDetail = ref<any>(false);
const projectForm = ref({ name: "", description: "" }); const taskForm = ref({ title: "", priority: "MEDIUM", important: false, urgent: false });
const visibleTasks = computed(() => selected.value ? tasks.value.filter(task => task.projectId === selected.value?.id) : tasks.value);
async function load() { loading.value = true; error.value = ""; try { const [p, t] = await Promise.all([http.get<unknown, unknown>("/planning/projects"), http.get<unknown, unknown>("/planning/tasks")]); projects.value = Array.isArray(p) ? p as Project[] : []; tasks.value = Array.isArray(t) ? t as Task[] : []; if (!selected.value && projects.value.length) selected.value = projects.value[0]; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "项目数据加载失败"; } finally { loading.value = false; } }
async function createProject() { if (!projectForm.value.name.trim()) { error.value = "项目名称不能为空"; return; } saving.value = true; try { await http.post("/planning/projects", { data: { name: projectForm.value.name.trim(), description: projectForm.value.description || null } }); dialog.value = false; projectForm.value = { name: "", description: "" }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "项目创建失败"; } finally { saving.value = false; } }
async function createTask() { if (!taskForm.value.title.trim() || !selected.value) return; saving.value = true; try { await http.post("/planning/tasks", { data: { ...taskForm.value, title: taskForm.value.title.trim(), projectId: selected.value.id } }); taskDialog.value = false; taskForm.value = { title: "", priority: "MEDIUM", important: false, urgent: false }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "任务创建失败"; } finally { saving.value = false; } }
async function complete(task: Task) { try { await http.post(`/planning/tasks/${task.id}/status/COMPLETED`, { headers: task.version == null ? undefined : { "If-Match": `\"${task.version}\"` } }); await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "任务状态更新失败"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">项目与任务</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">按项目组织任务，追踪状态、优先级和进度。</p></div><div class="flex gap-2"><el-button @click="dialog = true">新建项目</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-skeleton v-if="loading" :rows="10" animated/><div v-else class="grid grid-cols-1 lg:grid-cols-4 gap-5"><el-card shadow="never"><template #header><span class="font-medium">项目</span></template><el-empty v-if="!projects.length" description="暂无项目"/><div v-for="project in projects" :key="project.id" class="flex items-center gap-2 p-3 rounded cursor-pointer" :class="selected?.id === project.id ? 'bg-[var(--el-fill-color-light)]' : ''" @click="selected = project"><span class="flex-1 truncate">{{ project.name }}</span><el-tag size="small">{{ tasks.filter(task => task.projectId === project.id && task.status !== 'COMPLETED').length }}</el-tag></div></el-card><el-card shadow="never" class="lg:col-span-3"><template #header><div class="flex justify-between items-center"><div><span class="font-medium">{{ selected?.name || '全部任务' }}</span><el-tag v-if="selected?.status" class="ml-2">{{ selected.status }}</el-tag></div><el-button :disabled="!selected" @click="taskDialog = true">添加任务</el-button></div></template><el-empty v-if="!visibleTasks.length" description="暂无任务"/><el-table v-else :data="visibleTasks" stripe><el-table-column label="状态" width="70"><template #default="{ row }"><el-checkbox :model-value="row.status === 'COMPLETED'" @change="complete(row)"/></template></el-table-column><el-table-column prop="title" label="标题" min-width="220"/><el-table-column label="重要/紧急" width="120"><template #default="{ row }"><el-tag v-if="row.important" size="small">重要</el-tag><el-tag v-if="row.urgent" type="danger" size="small" class="ml-1">紧急</el-tag></template></el-table-column><el-table-column prop="deadline" label="截止时间" min-width="170"/><el-table-column prop="estimatedDurationMinutes" label="预计时长" width="100"/><el-table-column label="操作" width="80"><template #default="{ row }"><el-button link @click="taskDetail = row">详情</el-button></template></el-table-column></el-table></el-card></div><el-dialog v-model="dialog" title="新建项目" width="480px"><el-form label-position="top"><el-form-item label="名称" required><el-input v-model="projectForm.name"/></el-form-item><el-form-item label="描述"><el-input v-model="projectForm.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="createProject">创建</el-button></template></el-dialog><el-dialog v-model="taskDialog" title="添加任务" width="480px"><el-form label-position="top"><el-form-item label="标题" required><el-input v-model="taskForm.title"/></el-form-item><el-form-item label="优先级"><el-select v-model="taskForm.priority" class="w-full"><el-option label="低" value="LOW"/><el-option label="中" value="MEDIUM"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item><el-checkbox v-model="taskForm.important">重要</el-checkbox><el-checkbox v-model="taskForm.urgent">紧急</el-checkbox></el-form-item></el-form><template #footer><el-button @click="taskDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="createTask">创建</el-button></template></el-dialog><el-drawer v-model="taskDetail" title="任务详情" size="460px"><el-descriptions v-if="taskDetail" :column="1" border><el-descriptions-item label="标题">{{ taskDetail.title }}</el-descriptions-item><el-descriptions-item label="状态">{{ taskDetail.status }}</el-descriptions-item><el-descriptions-item label="截止时间">{{ taskDetail.deadline || '—' }}</el-descriptions-item><el-descriptions-item label="预计时长">{{ taskDetail.estimatedDurationMinutes || '—' }}</el-descriptions-item></el-descriptions></el-drawer></main></template>
